#!/usr/bin/env python3
import sys, os, re, gzip, json, csv, io, codecs
import xml.etree.ElementTree as ET
from decimal import Decimal, ROUND_HALF_UP
from datetime import datetime, date, timedelta, timezone

FACT = {'kg': Decimal(1), 'g': Decimal('0.001'), 'lb': Decimal('0.45392'), 'oz': Decimal('0.02837')}
ORDER = ['central', 'south', 'east', 'river', 'north', 'west', 'harbor', 'lakeside']
MONTHS = {m: i + 1 for i, m in enumerate('jan feb mar apr may jun jul aug sep oct nov dec'.split())}


def decode(b):
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    if b[:3] == b'\xef\xbb\xbf':
        return b[3:].decode('utf-8')
    if b[:2] == b'\xff\xfe':
        return b[2:].decode('utf-16-le')
    if b[:2] == b'\xfe\xff':
        return b[2:].decode('utf-16-be')
    enc = 'utf-8'
    head = b[:2000].decode('latin-1')
    for ln in head.split('\n'):
        m = re.match(r'#\s*charset\s*:\s*(\S+)', ln)
        if m:
            try:
                codecs.lookup(m.group(1))
                enc = m.group(1)
            except LookupError:
                pass
            break
    return b.decode(enc, errors='replace' if enc != 'utf-8' else 'strict') if enc != 'utf-8' else \
        b.decode('utf-8', errors='replace')


def idnum(s):
    m = re.search(r'(\d+)', s)
    return int(m.group(1)) if m else None


def norm_status(s):
    return re.sub(r'[\s\-]+', '_', s.strip().lower())


def parse_date(v, form):
    """return date or datetime(UTC-aware) -> returns date in UTC"""
    v = v.strip()
    m = re.match(r'^(\d{4})-(\d{2})-(\d{2})(?:[T ](.*))?$', v)
    if m:
        if m.group(4):
            try:
                dt = datetime.fromisoformat(v.replace(' ', 'T', 1) if 'T' not in v else v)
                if dt.tzinfo is not None:
                    dt = dt.astimezone(timezone.utc)
                return dt.date()
            except ValueError:
                pass
        return date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    m = re.match(r'^(\d{1,2})\s+([A-Za-z]{3})[a-z]*\.?\s+(\d{4})$', v)
    if m:
        return date(int(m.group(3)), MONTHS[m.group(2).lower()], int(m.group(1)))
    f = (form or 'iso').strip()
    fu = f.upper()
    if fu == 'SERIAL' or (re.fullmatch(r'\d{5}', v) and fu not in ('YYYYMMDD',)):
        return date(1899, 12, 30) + timedelta(days=int(float(v)))
    p = re.split(r'\D+', v)
    if fu in ('MM/DD/YYYY', 'MDY'):
        return date(int(p[2]), int(p[0]), int(p[1]))
    if fu in ('DD/MM/YYYY', 'DMY', 'DD.MM.YYYY'):
        return date(int(p[2]), int(p[1]), int(p[0]))
    if re.fullmatch(r'\d{8}', v):
        return date(int(v[:4]), int(v[4:6]), int(v[6:]))
    return date(int(p[0]), int(p[1]), int(p[2]))


def parse_weight(v, unit, decimal_comma, depot_unit_ok=True):
    v = v.strip()
    m = re.match(r'^(.*?)\s*(kg|g|lb|oz)$', v, re.I)
    if m:
        v, unit = m.group(1), m.group(2).lower()
    v = v.replace(' ', '')
    if decimal_comma:
        v = v.replace('.', '').replace(',', '.')
    else:
        v = v.replace(',', '')
    return Decimal(v) * FACT[unit]


COLS = {
    'east': {'id', 'type', 'shipped', 'gross', 'net', 'status', 'note'},
    'harbor': {'rec', 'ref', 'date', 'weight', 'state'},
    'lakeside': {'id', 'kind', 'booked', 'shipped', 'gross_kg', 'net_kg', 'status'},
    'river': {'t', 'ref', 'shipped', 'weight', 'status'},
    'west': {'id', 'typ', 'shipped', 'weight', 'status', 'note'},
}
DELIM = {'east': ',', 'lakeside': ',', 'harbor': '|', 'river': '\t', 'west': ';'}
TYPEMAP = {'': 'new', 'n': 'new', 'new': 'new', 'c': 'cor', 'cor': 'cor', 'corr': 'cor', 'correction': 'cor',
           'amend': 'cor', 'v': 'void', 'void': 'void'}
HSTATE = {'dlv': 'delivered', 'dll': 'delivered_late', 'can': 'cancelled', 'ret': 'returned', 'hld': 'held'}
FWSTATUS = {'D': 'delivered', 'L': 'delivered_late', 'C': 'cancelled', 'R': 'returned', 'H': 'held'}


def rec(num, typ, d, w, status):
    return {'num': num, 'type': typ, 'date': d, 'kg': w, 'status': status}


def logical_rows(text, delim):
    """yield ('comment', line) or ('row', fields)"""
    buf = None
    for ln in text.split('\n'):
        if ln.endswith('\r'):
            ln = ln[:-1]
        if buf is None:
            if not ln.strip():
                continue
            if ln.startswith('#'):
                yield 'comment', ln
                continue
            buf = ln
        else:
            buf += '\n' + ln
        if delim == ',':
            if buf.count('"') % 2 == 1:
                continue
            fields = next(csv.reader([buf], delimiter=','))
        else:
            fields = buf.split(delim)
        buf = None
        yield 'row', fields
    if buf is not None:
        yield 'row', next(csv.reader([buf], delimiter=',')) if delim == ',' else buf.split(delim)


def parse_delimited(depot, text):
    delim = DELIM[depot]
    cols = COLS[depot]
    seq = None
    dirs = {}
    hdr = None
    out = []
    for kind, x in logical_rows(text, delim):
        if kind == 'comment':
            m = re.match(r'#\s*(.+?)\s*:\s*(.*?)\s*$', x)
            if m:
                name = re.sub(r'\s+', ' ', m.group(1).lower())
                dirs[name] = m.group(2)
                if name == 'seq':
                    seq = int(m.group(2))
            else:
                m = re.search(r'seq\s*=\s*(\d+)', x)
                if m and seq is None:
                    seq = int(m.group(1))
            continue
        row = x
        low = [f.strip().lower() for f in row]
        if all(f in cols for f in low) and len(low) > 1:
            hdr = low
            continue
        if hdr is None:
            continue
        first = row[0].strip()
        if first.upper().startswith('TOTAL') or (depot == 'harbor' and first.startswith('#')):
            continue
        unit_row = None
        wcol = 'gross' if depot == 'east' else ('gross_kg' if depot == 'lakeside' else 'weight')
        if len(row) == len(hdr) + 1 and wcol in hdr:
            wi = hdr.index(wcol)
            if row[wi + 1].strip().lower() in FACT:
                unit_row = row[wi + 1].strip().lower()
                row = row[:wi + 1] + row[wi + 2:]
        if len(row) != len(hdr):
            continue
        r = dict(zip(hdr, [f.strip() for f in row]))
        idk = 'ref' if 'ref' in r else 'id'
        num = idnum(r[idk])
        if num is None:
            continue
        typ = TYPEMAP.get(r.get('type', r.get('rec', r.get('kind', r.get('typ', r.get('t', ''))))).lower())
        if typ is None:
            continue
        if typ == 'void':
            out.append(rec(num, 'void', None, None, None))
            continue
        dform = dirs.get('dates', dirs.get('date format'))
        if depot == 'river' and dform is None:
            dform = 'MM/DD/YYYY'
        if depot == 'east' and dform is None:
            dform = 'YMD'
        dv = r.get('shipped', r.get('date'))
        d = parse_date(dv, dform)
        # unit
        if depot == 'lakeside':
            unit = 'kg'
        elif unit_row:
            unit = unit_row
        else:
            u = dirs.get('weight unit', dirs.get('unit'))
            unit = (u.split()[0].lower() if u else None) or {'east': 'kg', 'river': 'kg', 'west': 'kg', 'harbor': 'kg'}[depot]
            if unit not in FACT:
                unit = 'kg'
        u = dirs.get('weight unit', '')
        dc = depot == 'west' or 'decimal comma' in u
        wv = r[wcol]
        w = parse_weight(wv, unit, dc)
        st = r.get('status', r.get('state', ''))
        st = HSTATE.get(st.lower(), norm_status(st)) if depot == 'harbor' else norm_status(st)
        out.append(rec(num, typ, d, w, st))
    return seq, out


def parse_fixed(text):
    LAY = {
        'FW1': (42, [('id', 0, 9), ('type', 9, 10), ('shipped', 10, 17), ('weight', 17, 25), ('status', 25, 26)]),
        'FW2': (43, [('type', 0, 1), ('id', 1, 10), ('shipped', 10, 18), ('weight', 18, 26), ('status', 26, 27)]),
        'FW3': (41, [('id', 0, 9), ('shipped', 9, 16), ('type', 16, 17), ('weight', 17, 24), ('status', 24, 25)]),
    }
    bylen = {v[0]: k for k, v in LAY.items()}
    cur = None
    seq = None
    out = []
    for ln in text.split('\n'):
        if ln.endswith('\r'):
            ln = ln[:-1]
        if '\f' in ln or not ln.strip():
            continue
        if ln.startswith('#'):
            m = re.match(r'#LAYOUT\s+(\S+)', ln)
            if m:
                cur = m.group(1)
            m = re.match(r'#SEQ\s+(\d+)', ln)
            if m:
                seq = int(m.group(1))
            continue
        name = cur if cur in LAY and len(ln) == LAY[cur][0] else bylen.get(len(ln))
        if name is None:
            ln2 = ln.rstrip()
            cand = [k for k, v in LAY.items() if v[0] >= len(ln2) and len(ln2) >= 25]
            if cur in LAY and len(ln2) >= 25 and len(ln2) <= LAY[cur][0]:
                name = cur
            else:
                continue
            ln = ln.ljust(LAY[name][0])
        f = {k: ln[a:b] for k, a, b in LAY[name][1]}
        num = idnum(f['id'])
        typ = TYPEMAP.get(f['type'].strip().lower())
        if num is None or typ is None:
            continue
        if typ == 'void':
            out.append(rec(num, 'void', None, None, None))
            continue
        s = f['shipped'].strip()
        if name == 'FW2':
            d = date(int(s[:4]), int(s[4:6]), int(s[6:8]))
        else:
            d = date(int(s[:4]), 1, 1) + timedelta(days=int(s[4:7]) - 1)
        n = Decimal(int(f['weight']))
        if name == 'FW1':
            w = n * FACT['g']
        elif name == 'FW2':
            w = n / 100
        else:
            w = n / 10 * FACT['lb']
        out.append(rec(num, typ, d, w, FWSTATUS.get(f['status'].strip().upper(), f['status'].strip().lower())))
    return seq, out


def parse_json(text):
    seq = None
    out = []
    for ln in text.split('\n'):
        ln = ln.strip()
        if not ln:
            continue
        try:
            v = json.loads(ln)
        except ValueError:
            continue
        objs = v if isinstance(v, list) else [v]
        for o in objs:
            if not isinstance(o, dict):
                continue
            if 'meta' in o and 'id' not in o:
                mt = o['meta']
                if isinstance(mt, dict) and 'seq' in mt:
                    seq = int(mt['seq'])
                continue
            if 'id' not in o:
                continue
            num = idnum(str(o['id']))
            typ = TYPEMAP.get(str(o.get('kind') or '').lower())
            if typ is None or num is None:
                continue
            if typ == 'void':
                out.append(rec(num, 'void', None, None, None))
                continue
            w = None
            for k, val in o.items():
                m = re.fullmatch(r'weight_(kg|g|lb|oz)', k)
                if m:
                    w = Decimal(str(val)) * FACT[m.group(1)]
            d = parse_date(o['shipped_at'], 'iso')
            out.append(rec(num, typ, d, w, norm_status(o.get('status', ''))))
    return seq, out


def parse_xml(b):
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    root = ET.fromstring(b)
    seq = int(root.get('seq')) if root.get('seq') else None
    ru = (root.get('weight-unit') or root.get('unit') or 'kg').lower()
    out = []
    for s in root.iter('shipment'):
        num = idnum(s.get('id', ''))
        typ = TYPEMAP.get((s.get('type') or '').lower())
        if num is None or typ is None:
            continue
        if typ == 'void':
            out.append(rec(num, 'void', None, None, None))
            continue
        sh = s.get('shipped')
        if sh is None:
            e = s.find('shipped')
            sh = e.text if e is not None else None
        d = parse_date(sh, 'iso')
        we = s.find('weight')
        unit = (we.get('unit') or s.get('weight-unit') or ru).lower()
        w = Decimal(we.text.strip().replace(',', '')) * FACT[unit]
        se = s.find('status')
        out.append(rec(num, typ, d, w, norm_status(se.text or '') if se is not None else ''))
    return seq, out


def parse_file(depot, path):
    b = open(path, 'rb').read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    if depot == 'central':
        return parse_xml(b)
    text = decode(b)
    if depot == 'south':
        return parse_fixed(text)
    if depot == 'north':
        return parse_json(text)
    return parse_delimited(depot, text)


def main():
    data_dir, out_file = sys.argv[1], sys.argv[2]
    files = {}
    for n in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, n)
        if os.path.isfile(p):
            files.setdefault(n.split('-')[0], []).append(p)
    corrections = resends = 0
    current = {}
    for depot, paths in files.items():
        parsed = []
        for i, p in enumerate(paths):
            seq, recs = parse_file(depot, p)
            parsed.append((seq if seq is not None else -1, i, recs))
        parsed.sort(key=lambda t: (t[0], t[1]))
        cur = {}
        for _, _, recs in parsed:
            for r in recs:
                if r['type'] == 'new':
                    if r['num'] in cur:
                        resends += 1
                    else:
                        cur[r['num']] = r
                elif r['type'] == 'cor':
                    cur[r['num']] = r
                    corrections += 1
                else:
                    cur.pop(r['num'], None)
                    corrections += 1
        current[depot] = cur
    rank = lambda d: ORDER.index(d) if d in ORDER else len(ORDER)
    owners = {}
    for depot in sorted(current, key=lambda d: (rank(d), d)):
        for num, r in current[depot].items():
            owners.setdefault(num, []).append((depot, r))
    handovers = sum(1 for v in owners.values() if len(v) > 1)
    deps = {d: [0, Decimal(0)] for d in files}
    months = {}
    for num, lst in owners.items():
        depot, r = lst[0]
        if r['status'] not in ('delivered', 'delivered_late'):
            continue
        deps[depot][0] += 1
        deps[depot][1] += r['kg']
        k = '%04d-%02d' % (r['date'].year, r['date'].month)
        m = months.setdefault(k, [0, Decimal(0)])
        m[0] += 1
        m[1] += r['kg']
    q = Decimal('0.01')
    f = lambda v: float(v.quantize(q, rounding=ROUND_HALF_UP))
    res = {
        'depots': {d: {'shipments': v[0], 'total_kg': f(v[1])} for d, v in sorted(deps.items())},
        'months': {k: {'shipments': v[0], 'total_kg': f(v[1])} for k, v in sorted(months.items())},
        'corrections_applied': corrections,
        'resends_dropped': resends,
        'handovers': handovers,
    }
    with open(out_file, 'w') as fh:
        json.dump(res, fh, indent=2)


main()
